import { useEffect, useState } from 'react';
import { ArrowUpRight, Database } from 'lucide-react';
import type { DemoData } from '../types';
import type { Dataset, Recording, Services } from '../services';
import ApprovedSourceLibrary from '../sourcing/ApprovedSourceLibrary';
import DatasetScout from '../sourcing/DatasetScout';

type Props = { services: Services; data: DemoData; onOpenRecording: (record: Recording) => Promise<void> };
const errorText = (error: unknown) => error instanceof Error ? error.message : 'The request failed.';

export default function DataWorkspace({ services, data, onOpenRecording }: Props) {
  const [datasets, setDatasets] = useState<Dataset[]>([]);
  const [datasetId, setDatasetId] = useState('');
  const [recordings, setRecordings] = useState<Recording[]>([]);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [catalogRevision, setCatalogRevision] = useState(0);
  const [approvedRevision, setApprovedRevision] = useState(0);

  useEffect(() => {
    let alive = true;
    if (services.connected) services.listDatasets().then(items => {
      if (!alive) return;
      setDatasets(items);
      setDatasetId(current => items.some(item => item.id === current) ? current : items[0]?.id ?? '');
    }).catch(reason => { if (alive) setError(`Could not load backend catalog: ${errorText(reason)}`); });
    return () => { alive = false; };
  }, [services]);

  useEffect(() => {
    let alive = true; setRecordings([]);
    if (services.connected && datasetId) services.listRecordings(datasetId)
      .then(items => { if (alive) setRecordings(items); })
      .catch(reason => { if (alive) setError(`Could not load recordings for this dataset: ${errorText(reason)}`); });
    return () => { alive = false; };
  }, [services, datasetId, catalogRevision]);

  async function open(record: Recording) {
    setBusy(record.id); setError('');
    try { await onOpenRecording(record); }
    catch (reason) { setError(errorText(reason)); }
    finally { setBusy(''); }
  }

  function refreshApprovedSources() {
    setApprovedRevision(value => value + 1);
    requestAnimationFrame(() => document.getElementById('approved-source-library')?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
  }

  return <section className="workspace-content" aria-labelledby="data-title">
    <header className="workspace-heading data-heading"><div><h1 id="data-title">Data sources</h1><p>Find robot telemetry, verify its evidence, and ingest an approved revision into TimeNet.</p></div><Database size={24} aria-hidden="true" /></header>
    {error && <p className="error-message" role="alert">{error}</p>}

    <details className="recording-summary">
      <summary><span><strong>Current recording</strong>{data.recording.name}</span><small>{data.recording.channelCount} channels · {data.recording.sampleRateHz.toLocaleString('en-US')} Hz · raw {data.detail.startSeconds.toFixed(3)}–{data.detail.endSeconds.toFixed(3)} s</small></summary>
      <div className="recording-details">
        <p><strong>{data.recording.id}</strong> · Recorded telemetry with a {data.recording.displaySampleRateHz} Hz overview. Outside the raw interval, Trace only shows display-resolution data.</p>
        <div className="field-row">{data.recording.sourceUrl && <a className="btn" href={data.recording.sourceUrl} target="_blank" rel="noopener noreferrer">Source dataset <ArrowUpRight size={14} aria-hidden="true" /></a>}<a className="btn" href="https://docs.timenet.ai" target="_blank" rel="noopener noreferrer">TimeNet documentation <ArrowUpRight size={14} aria-hidden="true" /></a></div>
        <div className="table-scroll"><table className="data-table"><caption>Loaded channel mapping</caption><thead><tr><th>Channel</th><th>Signal</th><th>Unit</th><th>Source sampling</th></tr></thead><tbody>{data.channels.map(channel => <tr key={channel.id}><td>{channel.id}</td><td>{channel.name}</td><td>{channel.unit}</td><td>{data.recording.sampleRateHz} Hz</td></tr>)}</tbody></table></div>
        <p className="status-note">Publisher markers are annotations, not verified physical collision-onset times. Original archive: {data.recording.archive}.</p>
      </div>
    </details>

    <DatasetScout services={services} onUseSource={refreshApprovedSources} />
    <div id="approved-source-library"><ApprovedSourceLibrary services={services} refreshKey={approvedRevision} onDatasetReady={id => { setDatasetId(id); setCatalogRevision(value => value + 1); }} /></div>

    {services.connected && <details className="catalog-summary"><summary><span><strong>Available recordings</strong>Open a recording already loaded by the backend.</span><small>{recordings.length} recording{recordings.length === 1 ? '' : 's'}</small></summary><div className="catalog-details"><label htmlFor="catalog-dataset">Dataset</label><select id="catalog-dataset" value={datasetId} onChange={event => setDatasetId(event.target.value)}><option value="">Select dataset</option>{datasets.map(dataset => <option key={dataset.id} value={dataset.id}>{dataset.name}</option>)}</select>{recordings.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Recording</th><th>Duration</th><th>Channels</th><th>Action</th></tr></thead><tbody>{recordings.map(record => <tr key={record.id}><td>{record.name}</td><td>{record.durationSec.toFixed(1)} s</td><td>{record.channels.length}</td><td><button className="btn" disabled={Boolean(busy)} onClick={() => void open(record)}>{busy === record.id ? 'Opening…' : 'Open recording'}</button></td></tr>)}</tbody></table></div> : <p className="empty-state">No recordings loaded for this dataset.</p>}</div></details>}
  </section>;
}
  }
  if (loading || !data) return <main className="loading-screen"><Waves size={28}/><h1>Trace</h1>{error ? <><p role="alert">{error}</p><button className="btn" onClick={() => void load()}>Retry loading recording</button></> : <><p>Opening the KUKA recording…</p><div className="loading-lines"><i/><i/><i/></div></>}</main>;
  return <Workbench key={`${datasetId}:${data.recording.id}:${data.demoCase?.id ?? "default"}`} data={data} datasetId={datasetId} onOpenRecording={openRecording} cases={cases} onOpenCase={openCase} caseLoading={caseLoading} caseError={caseError}/>;
}

function Workbench({ data: sourceData, datasetId, onOpenRecording, cases, onOpenCase, caseLoading, caseError }: { data: DemoData; datasetId: string; onOpenRecording: (recording: Recording) => Promise<void>; cases: DemoCase[]; onOpenCase: (id: string) => Promise<void>; caseLoading: boolean; caseError: string }) {
  const replay = useReplay(sourceData.recording.durationSeconds, sourceData.demoCase?.interval.start ?? Math.min(5.787, sourceData.recording.durationSeconds/3));
  const [visualMode, setVisualMode] = useState<'robot' | 'signals' | 'markers' | 'compare'>('robot');
  const [view, setView] = useState<'inspect' | 'data' | 'evaluation'>('inspect');
  const [mobile, setMobile] = useState<'signals' | 'assistant'>('signals');
  const [interval, setInterval] = useState<Interval>(sourceData.demoCase?.interval ?? { start: Math.min(5.787, sourceData.recording.durationSeconds/3), end: Math.min(6.811, sourceData.recording.durationSeconds) });
  const rawWindow = useRawWindow(sourceData, datasetId, interval, services);
  const data = rawWindow.data;
  const [following, setFollowing] = useState(false);
  const [zoom, setZoom] = useState(10);
  const [highlighted, setHighlighted] = useState<string[]>([]);
  const [robotPrediction, setRobotPrediction] = useState<PredictionCue>();
  const [replayStop, setReplayStop] = useState<number>();
  const timelineMarkers = useRef(new Map<string, HTMLButtonElement>());
  useEffect(() => {
    if (replayStop !== undefined && replay.playhead >= replayStop) { replay.seek(replayStop); setReplayStop(undefined); }
  }, [replay.playhead, replayStop, replay.seek]);
  const visiblePrediction = robotPrediction && robotPrediction.interval.start === interval.start && robotPrediction.interval.end === interval.end ? robotPrediction : undefined;
  function showRobotPrediction(prediction: PredictionCue) {
    setReplayStop(undefined); setRobotPrediction(prediction); setInterval({ ...prediction.interval });
    replay.seek(prediction.onsetSeconds); setFollowing(false); setHighlighted(prediction.channelId ? [prediction.channelId] : []);
    setView('inspect'); setMobile('signals'); setVisualMode('robot');
  }
  function openComparison(window: Interval) {
    replay.pause(); setReplayStop(undefined); setInterval({ ...window }); setVisualMode('compare'); setMobile('signals'); setView('inspect');
  }
  function replayInterval() {
    replay.seek(interval.start); replay.setSpeed(.5); setReplayStop(interval.end); setFollowing(true); replay.toggle();
  }
  const [draftStart, setDraftStart] = useState(interval.start.toFixed(3));
  const [draftEnd, setDraftEnd] = useState(interval.end.toFixed(3));
  const [selectionError, setSelectionError] = useState('');
  const registry = useModelRegistry(services);
  const availability = !services.connected ? 'Models not connected' : registry.loading ? 'Checking models…' : registry.error ? 'Model service unavailable' : registry.models.some(m => m.id === 'opentslm' && m.available) ? 'OpenTSLM connected' : 'Model unavailable';
  useEffect(() => { setDraftStart(interval.start.toFixed(3)); setDraftEnd(interval.end.toFixed(3)); }, [interval]);
  const previewChannels = useMemo(() => {
    if (highlighted.length && highlighted.length <= 2) return highlighted;
    try {
      return selectWindow(data, interval).channels.map(c => ({ id: c.id, range: Math.max(...c.values) - Math.min(...c.values) }))
        .sort((a, b) => b.range - a.range).slice(0, 2).map(c => c.id);
    } catch { return data.channels.slice(0, 2).map(c => c.id); }
  }, [data, interval, highlighted]);
  const viewport = useMemo(() => {
    if (following) return { start: zoom ? Math.max(0, replay.playhead-zoom) : 0, end: Math.max(.01, replay.playhead) };
    const padding = (interval.end-interval.start)*.18;
    return { start: Math.max(0, interval.start-padding), end: Math.max(.01, Math.min(data.recording.durationSeconds, interval.end+padding, replay.playhead)) };
  }, [following, zoom, interval, data.recording.durationSeconds, replay.playhead]);
  const validViewport = viewport.end > viewport.start ? viewport : { start: 0, end: Math.max(.01, replay.playhead) };
  // Playback moves the visual cursor, never the investigation's selected input.
  const effectiveInterval = interval;
  function select(next: Interval) { setReplayStop(undefined); if (next.start < 0 || next.end <= next.start || next.end > data.recording.durationSeconds) { setSelectionError('Choose a nonempty interval within this recording.'); return; } replay.pause(); setFollowing(false); setInterval(next); setSelectionError(''); }
  function seek(value: number) {
    setReplayStop(undefined); replay.seek(value); setFollowing(true); setHighlighted([]); setSelectionError('');
  }
  function marker(e: Marker) {
    setReplayStop(undefined);
    const context = markerWindow(e, data.recording.durationSeconds);
    replay.seek(context.start);
    setInterval(context);
    setVisualMode('robot');
    setMobile('signals');
    setFollowing(false);
    setHighlighted([]);
    setSelectionError('');
  }
  function navigateMarker(direction: number) {
    const target = direction > 0 ? data.events.find(e => e.timeSeconds > Math.max(interval.end, replay.playhead)) : [...data.events].reverse().find(e => e.timeSeconds < (effectiveInterval.start || replay.playhead));
    if (target) marker(target);
  }
  const selectedMarkerId = data.events.find(event => event.timeSeconds >= interval.start && event.timeSeconds < interval.end)?.id
    ?? data.events.find(event => event.timeSeconds >= replay.playhead)?.id
    ?? data.events.at(-1)?.id;
  function moveMarkerFocus(event: React.KeyboardEvent<HTMLButtonElement>, index: number) {
    const keyOffset = event.key === 'ArrowLeft' || event.key === 'ArrowUp' ? -1 : event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1 : 0;
