def _to_camel(value: str) -> str:
    head, *tail = value.split("_")
    return head + "".join(part.title() for part in tail)


class ImportedRecordSummary(BaseModel):
    model_config = ConfigDict(alias_generator=_to_camel, populate_by_name=True)

    record_id: str
    record_key: str = Field(pattern=r"^[a-f0-9]{24}$")
    series_count: int = Field(ge=0)
    value_count: int = Field(ge=0)
    duration_seconds: float | None = Field(default=None, ge=0)
    signals: list[str]
    annotation_keys: list[str]


class ImportedRecordPagination(BaseModel):
    model_config = ConfigDict(alias_generator=_to_camel, populate_by_name=True)

    page: int = Field(ge=1)
    page_size: int = Field(ge=1, le=100)
    total_items: int = Field(ge=0)
    total_pages: int = Field(ge=0)


class ImportedRecordPage(BaseModel):
    model_config = ConfigDict(alias_generator=_to_camel, populate_by_name=True)

    dataset_id: str
    dataset_version: str
    data: list[ImportedRecordSummary]
    pagination: ImportedRecordPagination


class ImportedDatasetUnavailable(RuntimeError):
    pass


class TimeNetClient(Protocol):
    def load(self, dataset_id: str, version: str | None = None, *, auto_build: bool): ...


class ImportedDatasetCatalog:
    """Read bounded record summaries from a validated ingestion registry."""

    def __init__(self, registry_root: Path, client: TimeNetClient | None = None):
        self.client = client or TimeNet(registry=registry_root)

    def list_records(
        self,
        dataset_id: str,
        dataset_version: str,
        *,
        page: int,
        page_size: int,
    ) -> ImportedRecordPage:
        if not re.fullmatch(r"[a-zA-Z0-9][a-zA-Z0-9._/-]{0,127}", dataset_id):
            raise ImportedDatasetUnavailable("Imported dataset identity is invalid")
        try:
            dataset = self.load_dataset(dataset_id, dataset_version)
        except Exception as exc:
            raise ImportedDatasetUnavailable(
                "Validated imported dataset is unavailable from the local registry"
            ) from exc
        records = dataset.records
        total_items = len(records)
        total_pages = math.ceil(total_items / page_size) if total_items else 0
        if total_pages and page > total_pages:
            raise ImportedDatasetUnavailable("Imported dataset page is out of range")
        start = (page - 1) * page_size
        summaries = [self._summary(record) for record in records[start : start + page_size]]
        return ImportedRecordPage(
            dataset_id=dataset_id,
            dataset_version=dataset_version,
            data=summaries,
            pagination=ImportedRecordPagination(
                page=page,
                page_size=page_size,
                total_items=total_items,
                total_pages=total_pages,
            ),
        )

    def load_dataset(self, dataset_id: str, dataset_version: str):
        if not re.fullmatch(r"[a-zA-Z0-9][a-zA-Z0-9._/-]{0,127}", dataset_id):
            raise ImportedDatasetUnavailable("Imported dataset identity is invalid")
        try:
            return self.client.load(
                dataset_id, version=dataset_version, auto_build=False
            )
        except Exception as exc:
            raise ImportedDatasetUnavailable(
                "Validated imported dataset is unavailable from the local registry"
            ) from exc

    def get_record(self, dataset_id: str, dataset_version: str, record_key: str):
        if not re.fullmatch(r"[a-f0-9]{24}", record_key):
            raise ImportedDatasetUnavailable("Imported record identity is invalid")
        matches = [
            record
            for record in self.load_dataset(dataset_id, dataset_version).records
            if imported_record_key(record.record_id) == record_key
        ]
        if len(matches) != 1:
            raise ImportedDatasetUnavailable("Imported record was not found")
        return matches[0]

    @staticmethod
    def _summary(record) -> ImportedRecordSummary:
        series = list(record.time_series)
        durations = [
            (item.n_values - 1) * item.time_axis.period_us / 1_000_000
            for item in series
            if item.n_values > 0 and getattr(item.time_axis, "period_us", None) is not None
        ]
        return ImportedRecordSummary(
            record_id=record.record_id,
            record_key=imported_record_key(record.record_id),
            series_count=len(series),
            value_count=sum(item.n_values for item in series),
            duration_seconds=max(durations) if durations else None,
            signals=sorted({str(item.signal) for item in series})[:20],
            annotation_keys=sorted({str(item.key) for item in record.annotations})[:20],
        )


def imported_record_key(record_id: str) -> str:
    return hashlib.sha256(record_id.encode()).hexdigest()[:24]

import type { DemoData, Interval } from '../types';
import type { SignalWindow } from '../services';

/** Validate identity, order, cadence and coverage before enabling model analysis. */
export function withRawWindow(data: DemoData, datasetId: string, interval: Interval, response: SignalWindow): DemoData {
  const ids = Array.from({ length: 7 }, (_, i) => `joint_${i + 1}`);
  const w = response.window;
  if (response.resolution !== 'raw' || w.datasetId !== datasetId || w.recordingId !== data.recording.id ||
      w.startSec !== interval.start || w.endSec !== interval.end || w.channelIds.join(',') !== ids.join(',') ||
      Math.abs(interval.end - interval.start - 1.024) > 1e-8 || response.series.length !== 7) {
    throw new Error('The raw response does not match this recording and selected model window.');
  }
  const channels = response.series.map((s, i) => {
    if (s.channelId !== ids[i] || s.values.length !== 1024 || s.timeSec.length !== 1024 ||
        s.values.some(v => typeof v !== 'number' || !Number.isFinite(v)) ||
        s.timeSec.some((t, j) => !Number.isFinite(t) || Math.abs(t - interval.start - j / 1000) > 1e-8)) {
      throw new Error('The raw response must contain seven ordered joints and 1,024 contiguous finite samples at 1 kHz.');
    }
    return { id: ids[i], name: data.channels[i].name, unit: data.channels[i].unit, values: s.values as number[] };
  });
  if (data.recording.sampleRateHz !== 1000 || channels.some(c => c.unit !== 'Nm')) throw new Error('Raw torque must use Nm at 1 kHz.');
  return { ...data, detail: { startSeconds: interval.start, endSeconds: interval.end, times: response.series[0].timeSec, channels } };
}
import type { DemoData, Interval } from '../types';
import { selectWindow } from './data';

export function modelWindowIssue(data: DemoData, interval: Interval, playhead: number): string | undefined {
  if (interval.end > playhead) return 'Move the replay cursor to the end of the selection.';
  if (interval.start < data.detail.startSeconds || interval.end > data.detail.endSeconds) return `Raw model input is available only within ${data.detail.startSeconds.toFixed(3)}–${data.detail.endSeconds.toFixed(3)} s.`;
  if (Math.abs(interval.end - interval.start - 1.024) > 1e-8) return 'OpenTSLM needs exactly 1.024 seconds (1,024 samples per joint).';
  try {
    const selected = selectWindow(data, interval);
    if (selected.resolution !== 'raw' || selected.sampleRateHz !== 1000 || selected.times.length !== 1024 ||
      selected.channels.some((c, i) => c.id !== `joint_${i + 1}`) ||
      selected.times.some((t, i) => Math.abs(t - interval.start - i / 1000) > 1e-8)) return 'Select 1,024 contiguous raw samples at 1 kHz.';
  } catch { return 'No raw model input is available for this selection.'; }
}

export function fitModelWindow(data: DemoData, interval: Interval, playhead: number): Interval | undefined {
  const first = data.detail.times[0];
  const lastEnd = Math.floor(Math.min(data.detail.endSeconds, playhead) * 1000 + 1e-8) / 1000;
  if (first === undefined || lastEnd - first < 1.024 - 1e-8) return;
  const start = Math.round(Math.max(first, Math.min(interval.start, lastEnd - 1.024)) * 1000) / 1000;
  const next = { start, end: Math.round((start + 1.024) * 1000) / 1000 };
  return modelWindowIssue(data, next, playhead) ? undefined : next;
}

export function checkpointLabel(revision?: string): string {
  const sha = revision?.match(/checkpoint-sha256:([a-f0-9]{64})/)?.[1];
  return sha === '8ff63b84ae5b64758f66b3e0527f4f225a04bb2b6b39193c806f58d94cec9f23' ? 'canary-v4 · 8ff63b84' : sha ? `Checkpoint ${sha.slice(0, 8)}` : 'Checkpoint unverified';
}

