    def __init__(self, runtime, data_path, catalog_path=None, raw_root=None, cnn_runtime=None):
        self.runtime = runtime
        self.cnn_runtime = cnn_runtime or CnnRuntime()
        raw = Path(data_path).read_bytes()
        self.data = json.loads(raw)
