                self.validate_window({"datasetId": DATASET_ID, "recordingId": case["recordingId"],
                    "startSec": case["interval"]["start"], "endSec": case["interval"]["end"],
                    "channelIds": [f"joint_{i}" for i in range(1, 8)]}, raw_only=True)
